#include "../defs.S"

// ─────────────────────────────────────────────────────────────────────
// Function Name: lookup_embedded
//
// Description: Look up a path in the embedded files table (generated by
//   embed_www.sh) by linear scan. References the external symbols
//   embedded_files and embedded_count (declared in the generated/stub
//   files); calls streqn.
//
//   Every pointer column in that table is an offset from embedded_files
//   itself rather than an address, so the binary needs no load-time
//   relocations and can be a position-independent executable on both
//   platforms (docs/SECURITY.md Step 13). This routine adds the table
//   base back, so its callers still receive real pointers.
//
//   A hash-based side table (FNV-1a keys, sorted for binary search) was
//   built for this lookup and never wired up. It was evaluated and
//   deliberately not adopted: embedded_count is 6, where the entire
//   hash table fits in two cache lines and binary search's data-dependent
//   branching is likely to cost more than it saves. See
//   docs/HISTORY.md for the measurement behind that call. If the
//   embedded asset count grows enough for this to matter, re-measure
//   before reintroducing that mechanism.
//
// Input/Arguments:
//   x0 -> path string (e.g. "www/index.html")
//   x1 -> path length
//
// Output/Returns:
//   x0 -> content pointer
//   x1 -> content size
//   x2 -> content-type string pointer
//   x3 -> content-type string length
//   x4 -> gzip flag (1 = gzipped, 0 = raw)
//   x5 -> ETag string pointer (e.g. "\"abc123...\"")
//   x6 -> ETag string length
//   carry set = not found, carry clear = found
//
// Clobbered Registers:
//   x0-x6, x9, x10, x11, x19, x20, x22, x23
//   (x19, x20, x22, x23 saved and restored)
//
// Stack Usage:
//   48 bytes: stp x29, x30, [sp, #-48]!
// ─────────────────────────────────────────────────────────────────────

.text
.align 2
FUNC lookup_embedded
    stp x29, x30, [sp, #-48]!
    stp x19, x20, [sp, #16]
    stp x22, x23, [sp, #32]

    mov x19, x0  // save path_ptr
    mov x20, x1  // save path_len

    adr_l x23, embedded_files    // x23 = running entry pointer
    adr_l x10, embedded_count
    ldr x22, [x10]                // x22 = count
    mov x9, #72                   // entry size
    mul x10, x22, x9              // x10 = count * entry_size
    add x22, x23, x10             // x22 = one-past-the-end pointer

Lle_scan:
    cmp x23, x22
    b.hs Lle_not_found

    ldr x3, [x23, #8]             // entry path_len
    cmp x20, x3                   // compare lengths
    b.ne Lle_next

    adr_l x11, embedded_files     // table base — re-derived per
                                  // iteration because streqn is free to
                                  // clobber x11
    ldr x1, [x23, #0]             // entry path offset
    add x1, x11, x1
    mov x0, x19
    mov x2, x20
    bl streqn
    cbnz x0, Lle_found

Lle_next:
    add x23, x23, x9              // advance to the next entry
    b Lle_scan

Lle_found:
    adr_l x11, embedded_files     // base again — the streqn that got us
                                  // here may have clobbered it
    // Entry layout at x23 (offsets are from embedded_files, in x11):
    // +0:  path_off    (8 bytes)
    // +8:  path_len    (8 bytes)
    // +16: content_off (8 bytes)
    // +24: content_size (8 bytes)
    // +32: ct_off      (8 bytes)
    // +40: ct_len      (8 bytes)
    // +48: gzip flag   (8 bytes)
    // +56: etag_off    (8 bytes)
    // +64: etag_len    (8 bytes)
    ldr x0, [x23, #16]   // content
    add x0, x11, x0
    ldr x1, [x23, #24]   // content_size
    ldr x2, [x23, #32]   // content-type
    add x2, x11, x2
    ldr x3, [x23, #40]   // ct_len
    ldr x4, [x23, #48]   // gzip flag
    ldr x5, [x23, #56]   // ETag
    add x5, x11, x5
    ldr x6, [x23, #64]   // etag_len

    cmn xzr, xzr  // clear carry
    b Lle_epilogue

Lle_not_found:
    cmp xzr, xzr  // set carry

Lle_epilogue:
    ldp x22, x23, [sp, #32]
    ldp x19, x20, [sp, #16]
    ldp x29, x30, [sp], #48
    ret
ENDFUNC lookup_embedded
